import 'dart:isolate';

class DesktopWorker {
  static Future<T> runInBackground<T, R>(T Function(R) task, R param) async {
    final port = ReceivePort();
    await Isolate.spawn(_entryPoint, [port.sendPort, task, param]);
    return await port.first as T;
  }

  static void _entryPoint(List<dynamic> args) {
    final sendPort = args[0] as SendPort;
    final task = args[1] as Function;
    final param = args[2];
    final result = task(param);
    sendPort.send(result);
  }
}
